<?php
$params=[];$where="d.ConflictStatus='Conflict Disclosed'";
$scopeId = (int) ($_GET['scholarship_id'] ?? 0);   // from the Evaluation Center: one scholarship only
if($scopeId){$where.=' AND a.ScholarshipID=?';$params[]=$scopeId;}
if(($_SESSION['role']??'')==='External_Admin'){$where.=' AND s.CreatedBy=?';$params[]=(int)$_SESSION['user_id'];}
$q=$pdo->prepare("SELECT d.*,ea.EvaluatorID OldEvaluatorID,a.Status ApplicationStatus,s.Name ScholarshipName,old.FirstName OldFirstName,old.LastName OldLastName,new.FirstName NewFirstName,new.LastName NewLastName FROM evaluation_conflict_declarations d JOIN evaluation_assignments ea ON ea.AssignmentID=d.AssignmentID JOIN application a ON a.ApplicationID=d.ApplicationID JOIN scholarship s ON s.ScholarshipID=a.ScholarshipID JOIN users old ON old.UserID=d.EvaluatorID LEFT JOIN users new ON new.UserID=d.ReassignedTo WHERE $where ORDER BY FIELD(d.ResolutionStatus,'Pending Reassignment','Reassigned','Cleared'),d.DeclaredAt DESC");$q->execute($params);$conflicts=$q->fetchAll(PDO::FETCH_ASSOC);
if(($_SESSION['role']??'')==='External_Admin'){$u=$pdo->prepare("SELECT UserID,FirstName,LastName,Organization FROM users WHERE Role='External_Admin' AND AccountStatus='Active' AND Organization=(SELECT Organization FROM users WHERE UserID=?) ORDER BY LastName");$u->execute([$_SESSION['user_id']]);$evaluators=$u->fetchAll(PDO::FETCH_ASSOC);}else{$evaluators=$pdo->query("SELECT UserID,FirstName,LastName,Organization FROM users WHERE Role='External_Admin' AND AccountStatus='Active' ORDER BY Organization,LastName")->fetchAll(PDO::FETCH_ASSOC);}
?>
<main class="flex-1 p-5 lg:p-10 lg:ml-72 bg-slate-50 min-h-screen"><div class="max-w-6xl mx-auto"><header class="mb-8"><p class="text-[11px] font-black uppercase tracking-widest text-red-600">Ethics and impartiality</p><h1 class="text-3xl font-black text-slate-900">Evaluator Conflicts</h1><p class="text-slate-500 mt-2">Conflicted evaluators are blocked from scoring. Every reassignment is retained in the assignment history and audit log.</p></header>
<?php foreach(['success'=>'green','error'=>'red'] as $key=>$color)if(isset($_SESSION[$key])):?><div class="mb-5 p-4 rounded-xl bg-<?=$color?>-50 border border-<?=$color?>-200 text-<?=$color?>-800 font-bold"><?=htmlspecialchars($_SESSION[$key]);unset($_SESSION[$key]);?></div><?php endif;?>
<div class="space-y-5"><?php foreach($conflicts as $c):?><article data-filter-resolution="<?=htmlspecialchars($c['ResolutionStatus'])?>" class="bg-white border <?= $c['ResolutionStatus']==='Pending Reassignment'?'border-red-300':'border-slate-200'?> rounded-2xl p-6 shadow-sm"><div class="flex flex-col lg:flex-row gap-6 justify-between"><div><div class="flex gap-2"><span class="px-3 py-1 rounded-full bg-red-50 text-red-700 text-[10px] font-black uppercase"><?=htmlspecialchars($c['RelationshipType'])?></span><span class="px-3 py-1 rounded-full bg-slate-100 text-slate-600 text-[10px] font-black uppercase"><?=htmlspecialchars($c['ResolutionStatus'])?></span></div><h2 class="text-xl font-black mt-3"><?=htmlspecialchars($c['ScholarshipName'])?> · Application #<?=(int)$c['ApplicationID']?></h2><p class="text-sm text-slate-500 mt-1">Disclosed by <?=htmlspecialchars($c['OldFirstName'].' '.$c['OldLastName'])?> on <?=htmlspecialchars($c['DeclaredAt'])?></p><p class="mt-3 text-sm text-slate-700"><strong>Disclosure:</strong> <?=htmlspecialchars($c['Details'])?></p><?php if($c['ReassignedTo']):?><p class="mt-3 text-sm font-bold text-green-700">Reassigned to <?=htmlspecialchars($c['NewFirstName'].' '.$c['NewLastName'])?> on <?=htmlspecialchars($c['ResolvedAt'])?></p><?php endif;?></div>
<?php if($c['ResolutionStatus']==='Pending Reassignment'):?><form action="../actions/process_evaluator_reassignment.php" method="post" class="lg:w-96 bg-slate-50 rounded-2xl p-4"><input type="hidden" name="declaration_id" value="<?=(int)$c['DeclarationID']?>"><label class="text-xs font-black uppercase text-slate-500">Replacement evaluator<select name="evaluator_id" required class="mt-2 w-full p-3 rounded-xl border border-slate-200"><option value="">Select evaluator…</option><?php foreach($evaluators as $e)if((int)$e['UserID']!==(int)$c['OldEvaluatorID']):?><option value="<?=(int)$e['UserID']?>"><?=htmlspecialchars($e['FirstName'].' '.$e['LastName'].' · '.$e['Organization'])?></option><?php endif;?></select></label><label class="block mt-3 text-xs font-black uppercase text-slate-500">Reassignment reason<textarea name="reason" required minlength="10" rows="3" class="mt-2 w-full p-3 rounded-xl border border-slate-200"></textarea></label><button class="mt-3 w-full py-3 rounded-xl bg-slate-900 text-white text-xs font-black uppercase">Reassign and audit</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$conflicts):?><div class="bg-white border border-slate-200 rounded-2xl p-12 text-center text-slate-500">No conflict disclosures recorded.</div><?php endif;?></div></div></main>
<?php include __DIR__ . '/article_pager.php'; ?>
